import{_ as T,c as t,a5 as i,o as a}from"./chunks/framework.mFcBg5UA.js";const e="/my-blog/question/network/http_and_https.jpg",r="/my-blog/img/yuque_mind.webp",d=JSON.parse('{"title":"HTTP和HTTPS的区别","titleTemplate":"前端面试题","description":"","frontmatter":{"outline":"deep","title":"HTTP和HTTPS的区别","titleTemplate":"前端面试题","head":[["link",{"rel":"canonical","href":"https://luffy-d-lufei.github.io/my-blog/question/network/http_and_https.html"}]]},"headers":[],"relativePath":"question/network/http_and_https.md","filePath":"question/network/http_and_https.md","lastUpdated":1724763327000}'),o={name:"question/network/http_and_https.md"};function P(n,l,H,s,h,p){return a(),t("div",null,l[0]||(l[0]=[i('<h1 id="http和https的区别" tabindex="-1">HTTP和HTTPS的区别 <a class="header-anchor" href="#http和https的区别" aria-label="Permalink to &quot;HTTP和HTTPS的区别&quot;">​</a></h1><img src="'+e+'" width="400" height="420"><h2 id="概念" tabindex="-1">概念 <a class="header-anchor" href="#概念" aria-label="Permalink to &quot;概念&quot;">​</a></h2><ul><li>HTTP(HyperText Transfer Protocol)：是超文本传输协议的缩写,是互联网上应用最为广泛的一种网络协议。它详细规定了浏览器和万维网服务器之间互相通信的规则。HTTP是无状态的、无连接的应用层协议。通信采用请求/响应模型,客户端(浏览器)向服务器发送请求,服务器根据请求返回响应内容。HTTP协议是由Tim Berners-Lee于1990年提出的,并在多年演化后成为互联网主流协议之一。</li><li>HTTPS(Hypertext Transfer Protocol Secure)：是HTTP的安全版本。它在HTTP的基础上加入SSL/TLS层,以安全的方式进行通信。HTTPS使用了加密、认证、完整性保护等手段,解决了HTTP不安全的缺点。HTTPS协议出现在1994年,最初由Netscape公司提出,经历了多年发展,现在已经成为网络传输安全的重要方式,被广泛使用。</li></ul><h2 id="默认端口" tabindex="-1">默认端口 <a class="header-anchor" href="#默认端口" aria-label="Permalink to &quot;默认端口&quot;">​</a></h2><ul><li>HTTP：协议默认使用80端口(TCP)。该端口专用于HTTP服务,是一个著名端口。在URL中可以省略端口号,直接使用<a href="http://xn--80-tz2cr9rdqa78w1qkxk0dyo5ate3b" target="_blank" rel="noreferrer">http://开头即默认为80端口</a>。HTTP使用80端口源于该端口未被占用。</li><li>HTTPS：协议默认使用443端口(TCP)。该端口同样也是一个著名端口,专用于HTTPS服务。在URL中可以省略端口号,直接使用<a href="https://xn--443-c88du2vltar11ag5l9i5d458a9e6b" target="_blank" rel="noreferrer">https://开头即默认为443端口</a>。HTTPS使用443端口是因为443未被占用且为80的443倍,可以表明其为安全版本。</li></ul><h2 id="连接方式" tabindex="-1">连接方式 <a class="header-anchor" href="#连接方式" aria-label="Permalink to &quot;连接方式&quot;">​</a></h2><p><img src="'+r+'" alt=""></p><ul><li>HTTP：是无连接状态的协议，HTTP直接建立在TCP(传输控制协议)之上。HTTP消息通过TCP连接直接以明文形式发送。每次请求都需要建立新的TCP连接,请求结束后连接会关闭。客户端直接发送HTTP请求给服务器,如果服务器可用,就返回HTTP响应,过程简单快速。</li><li>HTTPS：需要先建立SSL/TLS安全连接,再封装HTTP请求。客户端要验证服务器的数字证书和签名CA,确保服务器合法后,通过“SSL握手”协商加密算法,建立安全连接。连接建立后才会发送HTTPS请求。请求结束也不会关闭连接,能够复用连接。</li></ul><h2 id="使用场景" tabindex="-1">使用场景 <a class="header-anchor" href="#使用场景" aria-label="Permalink to &quot;使用场景&quot;">​</a></h2><ul><li>HTTP</li></ul><ol><li>访问一般性网站信息,如浏览博客、新闻等。</li><li>获取一般开放公共数据。</li><li>非敏感或不包含用户隐私的数据传输。</li><li>性能和效率要求较高的应用。</li><li>开发测试环境。</li></ol><ul><li>HTTPS</li></ul><ol><li>电子商务,金融,支付相关网站,如银行,电商,证券交易。</li><li>传输敏感信息的应用,如邮箱,管理系统。</li><li>身份认证环境,如登录注册。</li><li>涉及用户隐私的网站或应用。</li><li>安全性要求较高的系统。</li></ol><h2 id="安全性" tabindex="-1">安全性 <a class="header-anchor" href="#安全性" aria-label="Permalink to &quot;安全性&quot;">​</a></h2><ul><li>HTTP： HTTP协议传输的数据是明文的，容易被第三方窃听和截取，导致敏感信息泄露的风险</li><li>HTTPS： HTTPS协议通过使用SSL/TLS协议对通信数据进行加密，使得第三方无法直接获取传输的数据内容。这样可以防止敏感信息在传输过程中被拦截和窃取。</li></ul><p><strong>数据完整性：</strong></p><ul><li>HTTP： 在HTTP中，传输的数据可能会在传输过程中被篡改，因为没有机制来保证数据的完整</li><li>HTTPS： 通过使用加密和数字签名等技术，HTTPS确保传输的数据在传输过程中不会被篡改，保证数据的完整性。</li></ul><p><strong>身份认证：</strong></p><ul><li>HTTP： HTTP协议没有内建的身份认证机制，服务器和客户端之间的通信容易受到中间人攻击</li><li>HTTPS： 通过SSL/TLS协议，HTTPS确保通信双方的身份认证，防止中间人攻击和伪装。</li></ul><p><strong>安全证书：</strong></p><ul><li>HTTP： HTTP没有使用任何证书来验证服务器身份，也无法确保通信的目标服务器是否可信。</li><li>HTTPS： HTTPS使用数字证书，由受信任的证书颁发机构（CA）颁发，用于验证服务器的身份。这样用户可以确认他们正在与合法的服务器通信。</li></ul><h2 id="性能" tabindex="-1">性能 <a class="header-anchor" href="#性能" aria-label="Permalink to &quot;性能&quot;">​</a></h2><p><strong>握手和加密开销：</strong></p><ul><li>HTTP： HTTP传输数据时不涉及加密过程，因此通常会比较快速。</li><li>HTTPS： HTTPS在传输数据之前需要进行SSL/TLS握手和加密操作，这会增加一些延迟，特别是在初始连接时。但现代的硬件和加密算法优化已经减少了这种差距。</li></ul><p><strong>缓存效果：</strong></p><ul><li>HTTP： 在HTTP中，数据在传输过程中是明文的，这允许代理服务器和浏览器能够有效地缓存数据，从而提高性能。</li><li>HTTPS： 在HTTPS中，由于数据被加密，代理服务器和浏览器无法像HTTP那样有效地进行缓存，这可能会稍微影响性能。</li></ul><p><strong>HTTP/2和多路复用：</strong></p><ul><li>HTTP： HTTP/1.1存在“队头阻塞”问题，即同一时间只能处理一个请求，而其他请求需要等待。</li><li>HTTPS： HTTPS在HTTP/2协议中引入了多路复用（Multiplexing），允许同时处理多个请求，提高了并发性能和页面加载速度。</li></ul><p><strong>性能优化和CDN：</strong></p><ul><li>HTTP： HTTP上的性能优化技术（如CDN、缓存策略等）在一些场景下可以显著提升性能。</li><li>HTTPS： HTTPS也可以与性能优化技术结合，但由于加密和安全性的增加，可能会对某些性能优化策略产生一些影响</li></ul><h2 id="总结" tabindex="-1">总结 <a class="header-anchor" href="#总结" aria-label="Permalink to &quot;总结&quot;">​</a></h2><p>综合分析上述几个方面，HTTP和HTTPS在数据传输、安全性和性能等方面存在明显差异。HTTP虽然简单快速，但安全性不足；HTTPS通过加密技术提供了更高的安全性，但会引入一定的性能开销。根据具体的应用场景，选择适合的协议能够更好地平衡安全性和性能需求。在当今数字化时代，随着隐私和数据安全的重要性不断增加，HTTPS逐渐成为保护用户和网站之间通信的标准。</p>',33)]))}const S=T(o,[["render",P]]);export{d as __pageData,S as default};
